import XCTest

final class RoomUITests: XCTestCase {
    func testOpenTeamStandup() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 4) {
            openButton.tap()
        }

        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        let room = app.staticTexts["Team Standup"]
        XCTAssertTrue(room.waitForExistence(timeout: 10), "Team Standup should be visible in chats")
        room.tap()
        XCTAssertTrue(app.staticTexts["Team Standup"].waitForExistence(timeout: 5))
    }
}
EOF

